	/**
	 * One species' row, or null where the registry has grown past the pull.
	 *
	 * A species added after 2026-10-22 has no row here, and that is not an
	 * error: it is "not classified yet". Every caller treats null as
	 * "say nothing", never as WIDER — the difference between "we have not
	 * looked" and "we looked and found nothing" is the whole honesty of this
	 * table.
	 *
	 * @return array{class:string,n:string,date:string,url:string}|null
	 */
	public static function row( string $id ): ?array {
		return self::RECORDS[ $id ] ?? null;
	}

	/** HERE | NEAR | WIDER, or '' when the species is not in the pull. */
	public static function class_of( string $id ): string {
		$row = self::row( $id );
		return $row ? (string) $row['class'] : '';
	}

	/**
	 * Does this species belong in the guest's own list?
	 *
	 * HERE and NEAR both do — Rob's decision of 2026-10-22: a species
	 * recorded in Lake County but not within 15 km still shows under "Seen
	 * Here", wearing a "Lake County" chip. An unclassified species shows
	 * too, because the alternative is a guide that quietly drops a species
	 * nobody has got round to classifying.
	 */
	public static function seen_here( string $id ): bool {
		return 'WIDER' !== self::class_of( $id );
	}

	/** How many of the registry fall each way, for the pill counts. */
	public static function tally( array $ids ): array {
		$out = [ 'here' => 0, 'wider' => 0 ];
		foreach ( $ids as $id ) {
			$out[ self::seen_here( (string) $id ) ? 'here' : 'wider' ] += 1;
		}
		return $out;
	}
}
